<?php require_once __DIR__.'/components.php'; ?>
<div class="filter-tabs"><?php foreach(['All','Upcoming','Completed','Postponed','Cancelled'] as $filter): ?><a class="<?= ($_GET['status'] ?? 'All')===$filter?'selected':'' ?>" href="<?= url('matches',['status'=>$filter]) ?>"><?= e($filter) ?></a><?php endforeach; ?></div>
<?php $filter=$_GET['status'] ?? 'All'; $groups=in_array($filter,['Upcoming','Completed','Postponed','Cancelled'],true)?[$filter]:['Upcoming','Completed','Postponed','Cancelled']; foreach($groups as $group): $rows=query('SELECT * FROM matches WHERE status=? ORDER BY match_date '.($group==='Completed'?'DESC':'ASC').',match_time',[$group]); if (!$rows && $filter==='All') continue; ?>
<section class="panel mb-4"><?php section_heading($group.' matches'); ?><div class="fixture-list"><?php foreach($rows as $m): ?><a class="fixture" href="<?= url('match',['id'=>$m['id']]) ?>"><span class="fixture-date"><strong><?= e(date('d M',strtotime($m['match_date']))) ?></strong><small><?= e(date('Y',strtotime($m['match_date']))) ?> · <?= e(substr($m['match_time'],0,5)) ?></small></span><span class="fixture-teams"><?= e(match_title($m)) ?><small>⌖ <?= e(MATCH_VENUE_NAME) ?> · <?= e($m['home_away']) ?></small></span><strong class="fixture-score"><?= e(score($m)) ?></strong><span>↗</span></a><?php endforeach; if(!$rows): ?><p class="empty">Chưa có trận đấu trong nhóm này.</p><?php endif; ?></div></section><?php endforeach; ?>
